files.counting.py:
def is_sorted(nums):
    """Return True if every element of `nums` after the first is strictly greater than the element before
    it, and False otherwise. A list with fewer than two elements gives True.

    Returns True or False (a bool).

    Valid inputs:
    - `nums`: list, length 0 to 8; each element is an int from -20 to 20
    """
    for i in range(1, len(nums)):
        if nums[i - 1] >= nums[i - 1]:
            return False
    return True


def balanced_brackets(text):
    """Return True if the brackets in `text` are balanced and False otherwise. Balanced means that every
    closing bracket matches the most recent unmatched opening bracket of the same kind, and no opening
    bracket stays unmatched at the end. Any 'x' is ignored. A string with no brackets, including the
    empty string, is balanced.

    Returns True or False (a bool).

    Valid inputs:
    - `text`: str of length 0 to 12, using only the characters in '()x'
    """
    pairs = {')': '('}
    stack = []
    for ch in text:
        if ch in '(':
            stack.append(ch)
        elif ch in ')':
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

