def most_frequent(nums):
    """Return the value that occurs most often in `nums`. If several values share the largest number of
    occurrences, return the smallest of them. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if not nums:
        return None
    counts = {}
    for item in nums:
        counts[item] = counts.get(item, 0) + 1
    record = nums[0]
    for item in nums:
        if counts[item] > counts[record] or (counts[item] == counts[record] and item < record):
            record = item
    return record


def is_sorted(arr):
    """Return True if every element of `arr` after the first is greater than or equal to the element before
    it, and False otherwise. A list with fewer than two elements gives True.

    Returns True or False (a bool).

    Valid inputs:
    - `arr`: list, length 0 to 8; each element is an int from -20 to 20
    """
    for i in range(1, len(arr)):
        if arr[i - 1] > arr[i]:
            return False
    return True

