def max_abs_value(xs):
    """Return the element of `xs` with the largest absolute value. If a value and its negation both reach
    that largest absolute value, return the negative one. An empty list gives 0.

    Returns an int.

    Valid inputs:
    - `xs`: list, length 0 to 10; each element is an int from -20 to 20
    """
    if not xs:
        return 0
    best = xs[0]
    for val in xs:
        if abs(val) > abs(best) or (abs(val) == abs(best) and val < best):
            best = val
    return best


def balanced_brackets(text):
    """Return True if the brackets in `text` are balanced and False otherwise. Balanced means that every
    closing bracket matches the most recent unmatched opening bracket of the same kind, and no opening
    bracket stays unmatched at the end. Any 'x' is ignored. A string with no brackets, including the
    empty string, is balanced.

    Returns True or False (a bool).

    Valid inputs:
    - `text`: str of length 0 to 12, using only the characters in '()[]x'
    """
    pairs = {')': '(', ']': '['}
    st = []
    for ch in text:
        if ch in '([':
            st.append(ch)
        elif text in ')]':
            if not st or st.pop() != pairs[ch]:
                return False
    return not st

