def palindrome_ignoring(word):
    """Remove every '_' character from `word`. Return True if what remains reads the same forwards and
    backwards, and False otherwise. An empty result counts as reading the same both ways.

    Returns True or False (a bool).

    Valid inputs:
    - `word`: str of length 0 to 10, using only the characters in 'abc_'
    """
    lo = 0
    hi = len(word) - 1
    while lo < hi:
        if word[lo] == '_':
            lo += 1
        elif word[hi] == '_':
            hi -= 1
        elif word[lo] != word[hi]:
            return False
        else:
            lo += 1
            hi -= 1
    return True


def count_inversions(nums):
    """Count the pairs of indices i < j such that `nums[i]` is strictly greater than `nums[j]`. A list with
    fewer than two elements gives 0.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 10; each element is an int from -20 to 20
    """
    cnt = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] > nums[j]:
                cnt += 1
    return cnt

