def count_records(nums):
    """An element of `nums` is a record if it is strictly less than every element before it; the element at
    index 0 is always a record. Return the number of records. An empty list gives 0.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -20 to 20
    """
    if not nums:
        return 0
    top = nums[0]
    count = 1
    for x in nums[1:]:
        if x < top:
            top = x
            count += 1
    return count


def most_frequent(nums):
    """Return the value that occurs most often in `nums`. If several values share the largest number of
    occurrences, return the largest of them. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if not nums:
        return None
    counts = {}
    for item in nums:
        counts[item] = counts.get(item, 0) + 1
    best = nums[0]
    for item in nums:
        if counts[item] >= counts[best] or (counts[item] == counts[best] and item > best):
            best = item
    return best

