def two_sum(nums, target):
    """Find indices i < j (counting from 0) with `nums[i] + nums[j] == target`. If several pairs qualify,
    return the pair with the smallest j and, among those, the smallest i, as the list [i, j]. If no pair
    qualifies, return [].

    Returns a list [i, j] of two ints, or the empty list.

    Valid inputs:
    - `nums`: list, length 0 to 10; each element is an int from -20 to 20
    - `target`: int from -40 to 40
    """
    seen = {}
    for j, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], j]
        if x not in target:
            seen[x] = j
    return []


def max_abs_value(nums):
    """Return the element of `nums` with the largest absolute value. If a value and its negation both reach
    that largest absolute value, return the positive one. An empty list gives 0.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 10; each element is an int from -20 to 20
    """
    if not nums:
        return 0
    best = nums[0]
    for x in nums:
        if abs(x) > abs(best) or (abs(x) == abs(best) and x > best):
            best = x
    return best

