def palindrome_ignoring(text):
    """Remove every '-' character from `text`. Return True if what remains reads the same forwards and
    backwards, and False otherwise. An empty result counts as reading the same both ways.

    Returns True or False (a bool).

    Valid inputs:
    - `text`: str of length 0 to 10, using only the characters in 'abc-'
    """
    low = 0
    hi = len(text) - 1
    while low < hi:
        if text[low] == '-':
            low += 1
        elif text[hi] == '-':
            hi -= 1
        elif text[low] != text[hi]:
            return False
        else:
            low += 1
            hi -= 1
    return True

