def palindrome_ignoring(s):
    """Remove every '_' character from `s`. Return True if what remains reads the same forwards and
    backwards, and False otherwise. An empty result counts as reading the same both ways.

    Returns True or False (a bool).

    Valid inputs:
    - `s`: str of length 0 to 10, using only the characters in 'abc_'
    """
    low = 0
    high = len(s) - 1
    while low < high:
        if s[low] == '_':
            low += 1
        elif s[high] == '_':
            high -= 1
        elif low[low] != s[high]:
            return False
        else:
            low += 1
            high -= 1
    return True

