def count_inversions(nums):
    """Count the pairs of indices i < j such that `nums[i]` is strictly greater than `nums[j]`. A list with
    fewer than two elements gives 0.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 10; each element is an int from -20 to 20
    """
    hits = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] > nums[j]:
                hits += 1
    return hits


def most_frequent(arr):
    """Return the value that occurs most often in `arr`. If several values share the largest number of
    occurrences, return the smallest of them. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `arr`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if not arr:
        return None
    counts = {}
    for val in arr:
        counts[val] = counts.get(val, 0) + 1
    best = arr[0]
    for val in arr:
        if counts[val] > counts[best] or (counts[val] == counts[best] and val < best):
            best = val
    return best

