def spiral_order(table):
    """`table` is a list of rows. Return its elements in clockwise spiral order: start at the top-left
    cell, go right along the top row, down the right column, left along the bottom row, up the left
    column, then continue the same way inward until every cell has been listed exactly once. An empty
    matrix gives [].

    Returns a list of int.

    Valid inputs:
    - `table`: list of 0 to 4 rows (rectangular: all rows have the same length, 1 to 4 columns), each
      cell an int from -20 to 20
    """
    if not table:
        return []
    result = []
    top = 0
    bottom = len(table) - 1
    left = 0
    right = len(table[0]) - 1
    while top <= bottom and left <= right:
        for j in range(left, right + 1):
            result.append(table[top][j])
        top += 1
        for idx in range(top, bottom + 1):
            result.append(table[idx][right])
        right -= 1
        if top <= bottom:
            for j in range(right, left - 1, -1):
                result.append(table[bottom][j])
            bottom -= 1
        if left <= right:
            for idx in range(bottom, top - 1, -1):
                result.append(table[idx][left])
            left += 1
    return result


def most_frequent(nums):
    """Return the value that occurs most often in `nums`. If several values share the largest number of
    occurrences, return the largest of them. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if not nums:
        return None
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    best = nums[0]
    for x in nums:
        if counts[x] > counts[best] or (counts[x] == counts[best] and x > best):
            best = x
    return best

