def first_prefix_over(nums, t):
    """Return the smallest index i such that `nums[0] + nums[1] + ... + nums[i]` is strictly greater than
    `t`. If no such index exists (always the case for an empty list), return -1.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -10 to 10
    - `t`: int from -30 to 30
    """
    acc = 0
    for i, x in enumerate(nums):
        acc += x
        if acc > t:
            return i
