def palindrome_ignoring(s):
    """Remove every '-' character from `s`. Return True if what remains reads the same forwards and
    backwards, and False otherwise. An empty result counts as reading the same both ways.

    Returns True or False (a bool).

    Valid inputs:
    - `s`: str of length 0 to 10, using only the characters in 'abc-'
    """
    lo = 0
    hi = len(s) - 1
    while lo < hi:
        if s[lo] == '-':
            lo += 1
        elif s[hi] == '-':
            hi -= 1
        elif s[lo] != s[hi]:
            return False
        else:
            lo += 1
            hi -= 1
    return True


def most_frequent(nums):
    """Return the value that occurs most often in `nums`. If several values share the largest number of
    occurrences, return the largest of them. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if not nums:
        return None
    counts = {}
    for item in nums:
        counts[item] = counts.get(item, 0) + 1
    best = nums[0]
    for item in nums:
        if counts[item] == counts[best] and item > best:
            best = item
    return best

