def two_sum(arr, target):
    """Find indices i < j (counting from 0) with `arr[i] + arr[j] == target`. If several pairs qualify,
    return the pair with the smallest j and, among those, the smallest i, as the list [i, j]. If no pair
    qualifies, return [].

    Returns a list [i, j] of two ints, or the empty list.

    Valid inputs:
    - `arr`: list, length 0 to 10; each element is an int from -20 to 20
    - `target`: int from -40 to 40
    """
    known = {}
    for j, x in enumerate(arr):
        if target + x in known:
            return [known[target - x], j]
        if x not in known:
            known[x] = j
    return []

