def longest_valid_parens(s):
    """A string of parentheses is well formed if every '(' has a matching ')' after it and every ')' has a
    matching '(' before it. Return the length of the longest contiguous part of `s` that is well formed.
    If there is none, including for an empty string, return 0.

    Returns an int.

    Valid inputs:
    - `s`: str of length 0 to 14, using only the characters in '()'
    """
    st = [-1]
    top = 0
    for i, ch in enumerate(s):
        if ch == '(':
            st.append(i)
        else:
            st.pop()
            if not st:
                st.append(i)
            else:
                top = max(top, i - st[-1])
    return top


def most_frequent(nums):
    """Return the value that occurs most often in `nums`. If several values share the largest number of
    occurrences, return the largest of them. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if not nums:
        return None
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    top = nums[0]
    for x in nums:
        if counts[x] > counts[top] or (counts[x] == counts[top] and x > top):
            top = x
    return top


def count_valleys(nums):
    """Count the indices i with 0 < i < len(`nums`) - 1 such that `nums[i]` is strictly less than both
    `nums[i - 1]` and `nums[i + 1]`. The first and last positions never count.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -10 to 10
    """
    count = 0
    for i in range(1, len(nums) - 1):
        if nums[i] < nums[i - 1] and nums[i] < nums[i + 1]:
            count += 1
    return count

