    If there is none, including for an empty string, return 0.

    Returns an int.

    Valid inputs:
    - `s`: str of length 0 to 14, using only the characters in '()'
    """
    stack = [-1]
    best = 0
    for pos, ch in enumerate(s):
        if ch == '(':
            stack.append(pos)
        else:
            stack.pop()
            if not stack:
                stack.append(pos)
            else:
                best = max(best, pos - stack[-1])
    return best

