def lis_length(arr):
    """Return the length of the longest subsequence of `arr` (elements taken in their original order, not
    necessarily adjacent) whose values are nondecreasing. An empty list gives 0.

    Returns an int.

    Valid inputs:
    - `arr`: list, length 0 to 10; each element is an int from -20 to 20
    """
    if not arr:
        return 0
    dp = [1] * len(arr)
    for idx in range(1, len(arr)):
        for j in range(idx):
            if arr[j] <= arr[idx] and dp[j] + 1 > dp[idx]:
                dp[idx] = dp[j] + 1
    return max(dp)


def longest_common_prefix(items):
    """Return the longest string that is a prefix of every string in `items`. If `items` is empty or the
    strings have no common first character, return the empty string.

    Returns a str.

    Valid inputs:
    - `items`: list, length 0 to 5; each element is a str of length 0 to 6, using only the characters in
      'abc'
    """
    if not items:
        return ''
    prefix = items[0]
    for w in items[1:]:
        i = 0
        while i < len(prefix) and i < len(w) and (prefix[i] == w[i]):
            i += 1
        prefix = prefix[:i]
    return prefix

