def lis_length(nums):
    """Return the length of the longest subsequence of `nums` (elements taken in their original order, not
    necessarily adjacent) whose values are strictly increasing. An empty list gives 0.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 10; each element is an int from -20 to 20
    """
    if not nums:
        return 0
    table = [1] * len(nums)
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] > nums[i] and table[j] + 1 > table[i]:
                table[i] = table[j] + 1
    return max(table)

