def balanced_brackets(s):
    """Return True if the brackets in `s` are balanced and False otherwise. Balanced means that every
    closing bracket matches the most recent unmatched opening bracket of the same kind, and no opening
    bracket stays unmatched at the end. A string with no brackets, including the empty string, is
    balanced.

    Returns True or False (a bool).

    Valid inputs:
    - `s`: str of length 0 to 12, using only the characters in '()'
    """
    pairs = {')': '('}
    stack = []
    for ch in s:
        if ch in '(':
            stack.append(ch)
        elif ch in ')':
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not pairs


def count_valleys(nums):
    """Count the indices i with 0 < i < len(`nums`) - 1 such that `nums[i]` is strictly less than both
    `nums[i - 1]` and `nums[i + 1]`. The first and last positions never count.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -10 to 10
    """
    hits = 0
    for i in range(1, len(nums) - 1):
        if nums[i] < nums[i - 1] and nums[i] < nums[i + 1]:
            hits += 1
    return hits

