def count_inversions(values):
    """Count the pairs of indices i < j such that `values[i]` is strictly greater than `values[j]`. A list
    with fewer than two elements gives 0.

    Returns an int.

    Valid inputs:
    - `values`: list, length 0 to 10; each element is an int from -20 to 20
    """
    count = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] >= values[j]:
                count += 1
    return count

