def lis_length(xs):
    """Return the length of the longest subsequence of `xs` (elements taken in their original order, not
    necessarily adjacent) whose values are strictly increasing. An empty list gives 0.

    Returns an int.

    Valid inputs:
    - `xs`: list, length 0 to 10; each element is an int from -20 to 20
    """
    if not xs:
        return 0
    dp = [1] * len(xs)
    for i in range(1, len(xs)):
        for j in range(i):
            if xs[j] < xs[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)

