def longest_valid_parens(word):
    """A string of parentheses is well formed if every '(' has a matching ')' after it and every ')' has a
    matching '(' before it. Return the length of the longest contiguous part of `word` that is well
    formed. If there is none, including for an empty string, return 0.

    Returns an int.

    Valid inputs:
    - `word`: str of length 0 to 14, using only the characters in '()'
    """
    stack = [0]
    top = 0
    for pos, ch in enumerate(word):
        if ch == '(':
            stack.append(pos)
        else:
            stack.pop()
            if not stack:
                stack.append(pos)
            else:
                top = max(top, pos - stack[-1])
    return top

