def max_path_sum(board):
    """`board` is a list of rows. A path starts at the top-left cell, moves only one cell right or one cell
    down, and ends at the bottom-right cell. Its sum adds all the cells it visits, including the first
    and the last. Return the largest possible sum.

    Returns an int.

    Valid inputs:
    - `board`: list of 1 to 4 rows (rectangular: all rows have the same length, 1 to 4 columns), each
      cell an int from -9 to 9
    """
    rows = len(board)
    cols = len(board[0])
    cost = [row[:] for row in board]
    for r in range(rows):
        for q in range(cols):
            if r == 0 and q == 0:
                continue
            if r == 0:
                cost[r][q] += cost[r][q - 1]
            elif q == 0:
                cost[r][q] += cost[r - 1][q]
            else:
                cost[r][q] += max(cost[r - 1][q], cost[r][q - 1])
    return cost[rows - 1][cols - 1]

