def is_bipartite(n_nodes, edges):
    """An undirected graph has nodes 0 to `n_nodes` - 1, and each element [u, v] of `edges` is an edge
    between u and v. Return True if every node can be colored with one of two colors so that the two
    ends of every edge have different colors, and False otherwise. A self-loop [u, u] makes this
    impossible. A graph with no edges gives True.

    Returns True or False (a bool).

    Valid inputs:
    - `n_nodes`: int from 1 to 6
    - `edges`: list, length 0 to 8; each element is a list [u, v] where u is an int from 0 to 5, and
      less than `n_nodes`; v is an int from 0 to 5, and less than `n_nodes`
    """
    adj = [[] for _ in range(n_nodes)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * n_nodes
    for start in range(n_nodes):
        if color[start] != -1:
            continue
        color[start] = 0
        stack = [start]
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    stack.append(v)
                elif color[v] == color[u]:
                    return False
    return True

