def longest_pal_subseq(text):
    """Return the length of the longest subsequence of `text` (characters taken in their original order,
    not necessarily adjacent) that reads the same forwards and backwards. An empty string gives 0.

    Returns an int.

    Valid inputs:
    - `text`: str of length 0 to 9, using only the characters in 'abc'
    """
    n = len(text)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for idx in range(n - 1, -1, -1):
        dp[idx][idx] = 1
        for j in range(idx + 1, n):
            if text[idx] == text[j]:
                dp[idx][j] = dp[idx + 1][j - 1] + 2
            else:
                dp[idx][j] = max(dp[idx + 1][j], dp[idx][j - 1])
    return dp[0][n - 1]

